'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrnanmme = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnanmme, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a positive integer', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		-5,
		0,
		3.14,
		true,
		null,
		void 0,
		NaN,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			incrnanmme( value );
		};
	}
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.strictEqual( typeof incrnanmme( 3 ), 'function', 'returns a function' );
	t.end();
});

tape( 'the accumulator function computes a moving mean error incrementally', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var i;

	data = [
		[ 2, 3 ],
		[ 3, -1 ],
		[ 2, 5 ],
		[ 4, -4 ],
		[ 3, 0 ],
		[ -4, 5 ]
	];
	expected = [ 1, -1.5, 0, -3, -8/3, -2/3 ];
	acc = incrnanmme( 3 );

	for ( i = 0; i < data.length; i++ ) {
		actual = acc( data[ i ][ 0 ], data[ i ][ 1 ] );
		if ( actual === expected[ i ] ) {
			t.strictEqual( actual, expected[ i ], 'returns expected value' );
		} else {
			t.strictEqual( isnan( actual ), false, 'does not return NaN' );
		}
	}
	t.end();
});

tape( 'the accumulator function returns the current mean error if not provided input values', function test( t ) {
	var acc = incrnanmme( 2 );
	acc( 2, 3 );
	acc( 3, -5 );
	acc( 1, 10 );
	t.strictEqual( acc(), 0.5, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function returns `null` if no data has been provided', function test( t ) {
	var acc = incrnanmme( 3 );
	t.strictEqual( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function ignores NaN inputs', function test( t ) {
	var expected;
	var data;
	var acc;
	var v;
	var i;

	data = [
		[ NaN, 1 ],
		[ 1, NaN ],
		[ NaN, NaN ],
		[ 2, 2 ],
		[ NaN, 3 ]
	];
	expected = [ null, null, null, 0, 0 ];
	acc = incrnanmme( 3 );

	for ( i = 0; i < data.length; i++ ) {
		v = acc( data[ i ][ 0 ], data[ i ][ 1 ] );
		t.strictEqual( v, expected[ i ], 'returns expected value' );
	}
	t.end();
});
